#include <iostream>
#include <stdexcept>
#include <string>

void tryStoi(const std::string& text, int base = 10)
{
    std::size_t pos{};
    int value{std::stoi(text, &pos, base)};
    std::cout << '"' << text << "\" -> " << value << ", pos " << pos << '\n';
}

int main()
{
    tryStoi("42");
}
